<div class="modal-backdrop" x-show="modal" x-cloak x-transition.opacity.duration.150ms @click.self="closeModal()"><section class="modal-panel" x-show="modal" x-transition.opacity.scale.95.duration.150ms x-ref="modalPanel" @keydown.tab="trap($event)" role="dialog" aria-modal="true" aria-labelledby="modal-title">
<header class="modal-heading"><div><span class="modal-kicker" x-text="modal==='task'?'یک قدم در مسیر هدف':'فضای کار راستا'"></span><h2 id="modal-title" x-text="({task:taskForm.id?'ویرایش تسک':'تسک جدید',project:'یک پروژه تازه',stage:stageId?'ویرایش مرحله':'مرحله جدید',label:labelForm.id?'ویرایش برچسب':'برچسب جدید',goal:'هدف پروژه',member:'افزودن هم‌تیمی'})[modal]"></h2></div><button class="icon-btn" @click="closeModal()" aria-label="بستن فرم" x-html="$icon('X')"></button></header>
<template x-if="modal==='task'"><form class="task-composer todoist-task-modal" @submit.prevent="taskForm.id?saveTaskDetailsEdit():saveTask()">
<div class="task-modal-topbar">
    <div class="task-breadcrumb"><span>#</span><strong x-text="formProject?.name||'پروژه'"></strong><span>/</span><span x-text="selectedProductStage?.title||'بدون مرحله'"></span></div>
    <div class="task-top-actions"><button type="button" class="icon-btn" x-show="taskForm.id" @click="taskNeighbor(-1)" aria-label="تسک قبلی">↑</button><button type="button" class="icon-btn" x-show="taskForm.id" @click="taskNeighbor(1)" aria-label="تسک بعدی">↓</button><div x-data="{open:false}" class="task-more" @click.outside="open=false"><button type="button" class="icon-btn" @click="open=!open" aria-label="گزینه‌های تسک" x-html="$icon('MoreHorizontal')"></button><div class="dropdown-menu task-more-menu" x-show="open" x-transition.opacity.scale.95.duration.150ms><button class="danger-text" x-show="taskForm.id" type="button" @click="removeTask();open=false">حذف تسک</button></div></div><button type="button" class="icon-btn" @click="closeTaskComposer()" aria-label="بستن" x-html="$icon('X')"></button></div>
</div>
<div class="task-modal-grid">
<main class="task-modal-main">
    <div class="task-editor-row"><button type="button" class="completion task-main-completion" :class="{'checked':taskForm.completed_at||taskForm.completed}" @click="toggleTaskForm()"><span x-show="taskForm.completed_at||taskForm.completed" x-html="$icon('Check')"></span></button>
        <div class="task-editor-box" :class="{'is-editing':taskDetailsEditing}" @click="if(!taskDetailsEditing)startTaskDetailsEdit()">
            <template x-if="taskDetailsEditing"><div><input class="task-title-editor" x-model="taskForm.title" placeholder="نام تسک" required maxlength="200"><div class="task-description-editor"><span>≡</span><textarea x-model="taskForm.description" @input="autoGrow($event)" placeholder="توضیحات" rows="1" maxlength="10000"></textarea></div></div></template>
            <template x-if="!taskDetailsEditing"><div class="task-editor-preview"><h2 x-text="taskForm.title||'نام تسک'"></h2><p><span>≡</span><span x-text="taskForm.description||'توضیحات'"></span></p></div></template>
        </div>
    </div>
    <div class="task-editor-actions" x-show="taskDetailsEditing&&taskForm.id"><button type="button" class="button subtle" @click="cancelTaskDetailsEdit()">انصراف</button><button type="button" class="button primary" :disabled="taskSaving||!taskForm.title?.trim()" @click="saveTaskDetailsEdit()">ذخیره</button></div>
    <button type="button" class="add-subtask-link" @click="addSubtask()"><span x-html="$icon('Plus')"></span>افزودن زیرتسک</button>
    <div class="task-subtasks" x-show="taskForm.subtasks.length"><template x-for="(s,i) in taskForm.subtasks" :key="s.id||i"><div class="task-subtask-row" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="reorderSubtask(i);autosaveTaskNow()"><span class="subtask-drag" x-html="$icon('GripVertical')"></span><button type="button" class="subtask-completion" :class="{'checked':s.completed}" @click="s.completed=!s.completed;autosaveTaskNow()"><span x-show="s.completed" x-html="$icon('Check')"></span></button><input x-model="s.title" @change="autosaveTaskNow()" placeholder="عنوان زیرتسک" maxlength="200"><button type="button" class="icon-btn remove-subtask" @click="taskForm.subtasks.splice(i,1);autosaveTaskNow()" x-html="$icon('X')"></button></div></template></div>
    <div class="task-main-divider"></div>
    <div class="task-comment-composer" x-show="taskForm.id"><span class="avatar comment-avatar"><img x-show="user.avatar_url" :src="user.avatar_url" :alt="user.name"><span x-show="!user.avatar_url" :style="`background:${color(user.id)}`" x-text="initials(user.name)"></span></span><div class="comment-pill"><textarea x-model="commentText" @input="autoGrow($event)" placeholder="نظر بنویسید..." rows="1" maxlength="5000"></textarea><label class="comment-attach" aria-label="پیوست به نظر"><input type="file" multiple class="sr-only" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt" @change="commentFiles=[...commentFiles,...$event.target.files];$event.target.value=''"/><span x-html="$icon('Paperclip')"></span></label><button type="button" class="comment-send" x-show="commentText.trim()" x-transition.opacity.duration.150ms @click="addComment()" x-html="$icon('ArrowUpLeft')"></button></div></div>
    <div class="comment-file-queue" x-show="commentFiles.length"><template x-for="(f,i) in commentFiles" :key="i"><span><span x-html="$icon('Paperclip')"></span><span x-text="f.name"></span><button type="button" @click="commentFiles.splice(i,1)" x-html="$icon('X')"></button></span></template></div>
    <div class="task-comments" x-show="taskForm.id"><template x-for="c in taskForm.comments" :key="c.id"><div class="comment" :data-comment-id="c.id"><span class="avatar small"><img x-show="c.user?.avatar_url" :src="c.user?.avatar_url" :alt="c.user?.name"><span x-show="!c.user?.avatar_url" :style="`background:${color(c.member_id)}`" x-text="initials(c.user?.name)"></span></span><div class="comment-content"><div><strong x-text="c.user?.name"></strong><small x-text="commentTime(c.created_at)"></small></div><p x-show="!c.editing" x-text="c.body"></p><div class="comment-files"><template x-for="a in (taskForm.attachments||[]).filter(a=>a.comment_id===c.id)" :key="a.id"><a :href="'/attachments/'+a.id"><span x-html="$icon('Paperclip')"></span><span x-text="a.original_name"></span></a></template></div><div x-show="c.editing"><textarea x-model="c.editBody" @input="autoGrow($event)" rows="1"></textarea><div class="button-row"><button class="text-button accent" type="button" @click="editComment(c)">ذخیره</button><button class="text-button" type="button" @click="c.editing=false">لغو</button></div></div><div class="comment-actions" x-show="c.member_id===user.id"><button type="button" @click="c.editing=true;c.editBody=c.body">ویرایش</button><button type="button" class="danger-text" @click="deleteComment(c)">حذف</button></div></div></div></template></div>
    <details class="task-history-collapsed" x-show="taskForm.id"><summary><span x-html="$icon('History')"></span><span>تاریخچه</span><span x-text="fa((taskForm.activities||[]).length)"></span></summary><div class="task-history-list"><template x-for="a in taskForm.activities||[]" :key="a.id"><div class="activity-row"><span class="activity-dot"></span><div><p x-text="activityText(a)"></p><small x-text="relativeTime(a.created_at)"></small></div></div></template></div></details>
    <div class="new-task-submit" x-show="!taskForm.id"><button type="submit" class="button primary" :disabled="busy||!taskForm.title?.trim()||!taskForm.member_stage_id">افزودن تسک</button></div>
</main>
<aside class="task-details-panel">
    <div class="task-detail-row"><span class="task-detail-label">پروژه</span><div x-show="taskForm.id" class="task-detail-static"><span>#</span><span x-text="formProject?.name"></span></div><div x-show="!taskForm.id"><x-ui-select model="taskForm.project_id" options="projects.map(p=>({value:p.id,label:p.name}))" placeholder="انتخاب پروژه" change="projectChanged()" /></div></div>
    <div class="task-detail-row"><span class="task-detail-label">مرحله من</span><x-ui-select model="taskForm.member_stage_id" options="formMyStages.map(s=>({value:s.id,label:s.title}))" placeholder="انتخاب مرحله من" change="memberStageChanged();autosaveTaskNow()" /><div class="task-product-stage-readonly" x-show="selectedProductStage"><span>مرحله محصول</span><strong x-text="selectedProductStage?.title"></strong></div><button type="button" class="task-detail-add" @click="startInlineStage()"><span x-html="$icon('Plus')"></span>ساخت مرحله من</button></div>
    <div class="inline-stage-side" x-show="inlineStage"><label>مرحله محصول مادر<x-ui-select model="inlineStageForm.product_stage_id" options="(formProject?.stages||[]).map(s=>({value:s.id,label:s.title}))" placeholder="انتخاب مرحله محصول" /></label><label>عنوان مرحله<input x-model="inlineStageForm.title" placeholder="مثلاً بررسی نهایی"></label><div class="button-row"><button type="button" class="button primary small-button" @click="createInlineStage()">ساخت</button><button type="button" class="button subtle small-button" @click="inlineStage=false">لغو</button></div></div>
    <div class="task-detail-row"><span class="task-detail-label">تاریخ</span><button type="button" class="task-detail-value task-date-value" @click="openTaskDate($event.currentTarget)"><span x-html="$icon('CalendarDays')"></span><span x-text="taskDateLabel()"></span><span x-html="$icon('Plus')"></span></button></div>
    <template x-teleport="body"><div class="task-date-popover" x-show="taskDateOpen" x-cloak x-transition.opacity.scale.95.duration.150ms :style="taskDateStyle" @click.outside="taskDateOpen=false" @keydown.escape.stop="taskDateOpen=false"><div class="task-date-tabs"><button type="button" :class="{'selected':taskDateMode==='single'}" @click="taskDateMode='single';taskDatePickingEnd=false">یک روز</button><button type="button" :class="{'selected':taskDateMode==='range'}" @click="taskDateMode='range';taskDatePickingEnd=false">بازه</button></div><div class="task-date-shortcuts"><button type="button" @click="taskDateShortcut('today')">امروز</button><button type="button" @click="taskDateShortcut('tomorrow')">فردا</button><button type="button" @click="taskDateShortcut('nextweek')">هفته بعد</button><button type="button" @click="taskDateShortcut('none')">بدون تاریخ</button></div><div class="calendar-head"><button type="button" class="icon-btn" @click="moveTaskDate(-1)" x-html="$icon('ChevronRight')"></button><strong x-text="taskDateHeading()"></strong><button type="button" class="icon-btn" @click="moveTaskDate(1)" x-html="$icon('ChevronLeft')"></button></div><div class="calendar-grid task-range-calendar"><template x-for="d in ['ش','ی','د','س','چ','پ','ج']"><span class="muted" x-text="d"></span></template><template x-for="day in taskDateDays" :key="day.iso"><button type="button" :class="taskDateClass(day)" @click="pickTaskDate(day.iso)" x-text="day.label"></button></template></div></div></template>
    <div class="task-detail-row" x-data="{open:false,style:'',position(){const r=$refs.trigger.getBoundingClientRect();const w=260;const left=Math.max(12,Math.min(innerWidth-w-12,r.left));const top=Math.min(innerHeight-340,r.bottom+6);style=`position:fixed;top:${Math.max(12,top)}px;left:${left}px;width:${w}px`}}" @keydown.escape.stop="open=false"><span class="task-detail-label">برچسب‌ها</span><button type="button" class="task-detail-value" x-ref="trigger" @click="open=!open;if(open)$nextTick(()=>position())"><span x-text="taskForm.labels.length?fa(taskForm.labels.length)+' برچسب':'افزودن برچسب'"></span><span x-html="$icon('Plus')"></span></button><template x-teleport="body"><div class="task-side-popover checklist-popover labels-popover fixed-popover" x-show="open" x-cloak x-transition.opacity.scale.95.duration.150ms :style="style" @click.outside="open=false"><input x-model="labelQuery" placeholder="جست‌وجوی برچسب"><template x-for="l in formLabels" :key="l.id"><label><input type="checkbox" :value="l.id" x-model.number="taskForm.labels" @change="autosaveTaskNow()"><span class="label-color-dot" :style="`background:${l.color}`"></span><span x-text="l.name"></span></label></template><button type="button" class="accent create-label-option" x-show="labelQuery&&!formLabels.some(l=>l.name===labelQuery)" @click="quickLabel()"><span x-html="$icon('Plus')"></span><span x-text="'ساخت برچسب «'+labelQuery+'»'"></span></button></div></template></div>
    <div class="task-detail-row" x-data="{open:false,style:'',position(){const r=$refs.trigger.getBoundingClientRect();const w=280;const left=Math.max(12,Math.min(innerWidth-w-12,r.left));const top=Math.min(innerHeight-320,r.bottom+6);style=`position:fixed;top:${Math.max(12,top)}px;left:${left}px;width:${w}px`}}" @keydown.escape.stop="open=false"><span class="task-detail-label">پیوست‌ها</span><button type="button" class="task-detail-value" x-ref="trigger" @click="open=!open;if(open)$nextTick(()=>position())"><span x-text="fa((taskForm.attachments||[]).length+pendingFiles.length)+' فایل'"></span><span x-html="$icon('Plus')"></span></button><template x-teleport="body"><div class="task-side-popover attachments-popover fixed-popover" x-show="open" x-cloak x-transition.opacity.scale.95.duration.150ms :style="style" @click.outside="open=false"><label class="attachment-add"><input type="file" class="sr-only" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt" @change="filesAdded($event.target.files);$event.target.value=''"/><span x-html="$icon('Paperclip')"></span>افزودن فایل</label><template x-for="a in taskForm.attachments||[]" :key="a.id"><div class="side-attachment"><span x-html="$icon('Paperclip')"></span><a :href="'/attachments/'+a.id"><strong x-text="a.original_name"></strong><small x-text="size(a.size)"></small></a><button type="button" class="icon-btn" x-show="a.member_id===user.id" @click="deleteAttachment(a)" x-html="$icon('X')"></button></div></template><template x-for="(f,i) in pendingFiles" :key="i"><div class="side-attachment"><span x-html="$icon('Paperclip')"></span><span><strong x-text="f.name"></strong><small x-text="size(f.size)"></small></span><button type="button" class="icon-btn" @click="pendingFiles.splice(i,1)" x-html="$icon('X')"></button></div></template></div></template></div>
</aside>
</div>
</form></template>
<template x-if="modal==='project'"><form @submit.prevent="projectStep<3?nextStep():saveProject()"><div class="wizard-steps"><template x-for="(title,i) in ['اطلاعات پروژه','هدف پروژه','مراحل مسیر']" :key="i"><div :class="{'current':projectStep===i+1,'done':projectStep>i+1}"><span x-text="projectStep>i+1?'✓':fa(i+1)"></span><strong x-text="title"></strong></div></template></div><div class="modal-body"><div x-show="projectStep===1"><div class="form-intro"><h3>چه چیزی می‌خواهید بسازید؟</h3><p>با یک نام و توضیح کوتاه، به پروژه‌تان هویت بدهید.</p></div><label>رنگ پروژه<input type="color" x-model="projectForm.color"></label><label>نام پروژه<input x-model="projectForm.name" placeholder="نام پروژه شما" maxlength="150"><small class="field-error" x-text="err('name')"></small></label><label>توضیح کوتاه<textarea x-model="projectForm.description" placeholder="این پروژه درباره چیست؟" rows="3"></textarea></label></div><div x-show="projectStep===2"><div class="helper-box"><span x-html="$icon('Target')"></span><p>ابتدا هدف پروژه را مشخص کنید. مراحل پروژه، مسیر رسیدن به این هدف خواهند بود.</p></div><label>عنوان هدف<input x-model="projectForm.goal.title" placeholder="می‌خواهیم به چه نتیجه‌ای برسیم؟"><small class="field-error" x-text="err('goal.title')"></small></label><label>توضیح هدف<textarea x-model="projectForm.goal.description" rows="2" placeholder="هدف را کمی بیشتر توضیح دهید..."></textarea></label><label>معیار موفقیت<textarea x-model="projectForm.goal.success_criterion" rows="2" placeholder="از کجا بفهمیم به هدف رسیده‌ایم؟"></textarea><small class="field-error" x-text="err('goal.success_criterion')"></small></label><div class="form-grid"><label>تاریخ شروع<x-date-picker model="projectForm.goal.start_date" /><small class="field-error" x-text="err('goal.start_date')"></small></label><label>تاریخ هدف<x-date-picker model="projectForm.goal.target_date" /><small class="field-error" x-text="err('goal.target_date')"></small></label></div></div><div x-show="projectStep===3"><div class="form-intro"><h3>مسیر رسیدن به هدف را بسازید</h3><p>مرحله‌ها را بکشید و به ترتیب دلخواه بچینید.</p></div><template x-for="(s,i) in projectForm.stages" :key="i"><div class="wizard-stage" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="dropWizard(i)"><div class="wizard-stage-title"><span x-html="$icon('GripVertical')"></span><span class="step-number" x-text="fa(i+1)"></span><input x-model="s.title" placeholder="نام مرحله"><button type="button" class="icon-btn" @click="moveWizard(i,-1)" aria-label="مرحله قبل" x-html="$icon('ChevronRight')"></button><button type="button" class="icon-btn" @click="projectForm.stages.splice(i,1)" aria-label="حذف مرحله" x-html="$icon('Trash2')"></button></div><input x-model="s.description" placeholder="توضیح کوتاه (اختیاری)"><div class="form-grid"><label>شروع<x-date-picker model="s.start_date" /></label><label>پایان<x-date-picker model="s.end_date" /></label></div><small class="field-error" x-text="Object.keys(errors).filter(k=>k.startsWith('stages.'+i+'.')).map(k=>err(k)).join(' ')"></small></div></template><button type="button" class="button full-width dashed" @click="projectForm.stages.push({title:'',description:'',start_date:projectForm.goal.start_date,end_date:projectForm.goal.target_date})"><span x-html="$icon('Plus')"></span>افزودن مرحله</button><small class="field-error" x-text="err('stages')"></small></div></div><footer class="modal-footer"><span class="muted" x-text="'مرحله '+fa(projectStep)+' از ۳'"></span><div class="button-row"><button type="button" class="button" @click="projectStep>1?projectStep--:closeModal()" x-text="projectStep>1?'قبلی':'انصراف'"></button><button class="button primary" type="submit" :disabled="busy" x-text="busy?'در حال ساخت...':projectStep===3?'ساخت پروژه':'ادامه'"></button></div></footer></form></template>
<template x-if="modal==='stage'"><form @submit.prevent="saveStage()"><div class="modal-body"><div class="helper-box" x-show="stageUser"><span x-html="$icon('Users')"></span><p x-text="'مسیر اختصاصی '+stageUser?.name"></p></div><label x-show="stageUser">زیرمجموعه مرحله محصول<x-ui-select model="stageForm.product_stage_id" options="(stageProject?.stages||[]).map(s=>({value:s.id,label:s.title}))" placeholder="انتخاب مرحله محصول" /><small class="field-error" x-text="err('product_stage_id')"></small></label><label>نام مرحله<input x-model="stageForm.title" required maxlength="120"><small class="field-error" x-text="err('title')"></small></label><label>توضیحات<textarea x-model="stageForm.description" rows="3"></textarea></label><div class="form-grid"><label>شروع<x-date-picker model="stageForm.start_date" /><small class="field-error" x-text="err('start_date')"></small></label><label>پایان<x-date-picker model="stageForm.end_date" /><small class="field-error" x-text="err('end_date')"></small></label></div></div><footer class="modal-footer"><button type="button" class="text-button danger-text" x-show="stageId&&canWrite(stageProject)" @click="deleteStage({...stageForm,id:stageId,project_id:stageProjectId},stageKind,stageUser)">حذف مرحله</button><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy||!canWrite(stageProject)">ذخیره مرحله</button></div></footer></form></template>
<template x-if="modal==='goal'"><form @submit.prevent="saveGoal()"><div class="modal-body"><label>عنوان هدف<input x-model="goalForm.title" required><small class="field-error" x-text="err('title')"></small></label><label>توضیح هدف<textarea x-model="goalForm.description" rows="3"></textarea></label><label>معیار موفقیت<textarea x-model="goalForm.success_criterion" required rows="3"></textarea><small class="field-error" x-text="err('success_criterion')"></small></label><div class="form-grid"><label>شروع<x-date-picker model="goalForm.start_date" /></label><label>پایان<x-date-picker model="goalForm.target_date" /><small class="field-error" x-text="err('end_date')"></small></label></div></div><footer class="modal-footer"><span></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy">ذخیره هدف</button></div></footer></form></template>
<template x-if="modal==='label'"><form class="label-modal-form" @submit.prevent="saveLabel()"><div class="modal-body"><label>نام برچسب<input x-model="labelForm.name" required maxlength="60" placeholder="نام برچسب"><small class="field-error" x-text="err('name')"></small></label><fieldset class="label-palette"><legend>رنگ</legend><template x-for="c in ['#d9693a','#e58a45','#c99a35','#6f9b66','#4f9b86','#4f8fa8','#5877b9','#7a68b3','#9a63a6','#b76583','#b85c5c','#7b7f79']" :key="c"><button type="button" class="label-color-choice" :style="`--choice:${c}`" :class="{'chosen':labelForm.color===c}" @click="labelForm.color=c" :aria-label="'انتخاب رنگ '+c"><span></span><i x-show="labelForm.color===c" x-html="$icon('Check')"></i></button></template></fieldset></div><footer class="modal-footer"><button type="button" class="button subtle" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy||!labelForm.name?.trim()">ذخیره برچسب</button></footer></form></template>
</section></div>
